// The language reference: one index per language, generated by
// tools/gen-*-ref.mjs into reference/*.json and loaded on first use. The
// panel, completion, hover and signature hints all read from here.

import MiniSearch from 'minisearch';

import type { LanguageId } from '$lib/adapters/types';

export interface RefParam {
  name: string;
  type?: string;
  doc?: string;
}

export interface RefEntry {
  name: string;
  aliases?: string[];
  signature?: string;
  params?: RefParam[];
  /** One line. */
  synopsis: string;
  /** Markdown; its code blocks are runnable examples too. */
  description: string;
  examples: string[];
  tags: string[];
  deprecated?: boolean;
}

interface RefFile {
  language: LanguageId;
  version: string;
  entries: RefEntry[];
}

const files: Record<LanguageId, () => Promise<{ default: RefFile }>> = {
  strudel: () => import('../../../reference/strudel.json') as Promise<{ default: RefFile }>,
  tidal: () => import('../../../reference/tidal.json') as Promise<{ default: RefFile }>,
};

export class Reference {
  readonly language: LanguageId;
  readonly version: string;
  readonly entries: RefEntry[];
  /** Tags, most used first. */
  readonly tags: string[];
  private byName = new Map<string, RefEntry>();
  private index: MiniSearch<{ id: number; name: string; aliases: string; synopsis: string; tags: string }>;

  constructor(file: RefFile) {
    this.language = file.language;
    this.version = file.version;
    this.entries = file.entries;
    for (const e of this.entries) {
      this.byName.set(e.name, e);
      for (const alias of e.aliases ?? []) if (!this.byName.has(alias)) this.byName.set(alias, e);
    }
    const counts = new Map<string, number>();
    for (const e of this.entries) for (const t of e.tags) counts.set(t, (counts.get(t) ?? 0) + 1);
    this.tags = [...counts].sort((a, b) => b[1] - a[1]).map(([t]) => t);
    this.index = new MiniSearch({
      fields: ['name', 'aliases', 'synopsis', 'tags'],
      searchOptions: { boost: { name: 6, aliases: 4, tags: 2 }, prefix: true, fuzzy: 0.2 },
    });
    this.index.addAll(
      this.entries.map((e, id) => ({ id, name: e.name, aliases: (e.aliases ?? []).join(' '), synopsis: e.synopsis, tags: e.tags.join(' ') })),
    );
  }

  /** The entry for a name or alias. */
  get(name: string): RefEntry | undefined {
    return this.byName.get(name);
  }

  /**
   * Entries matching `query` (fuzzy, by name first), within `tag` if given.
   * No query lists everything, documented entries first.
   */
  search(query: string, tag: string | null = null): RefEntry[] {
    const inTag = (e: RefEntry) => !tag || e.tags.includes(tag);
    const q = query.trim();
    if (!q) {
      const documented = (e: RefEntry) => (e.description ? 0 : 1);
      return this.entries.filter(inTag).sort((a, b) => documented(a) - documented(b) || a.name.localeCompare(b.name));
    }
    const exact = this.get(q);
    const hits = this.index.search(q).map((r) => this.entries[r.id as number]);
    return [...new Set([...(exact ? [exact] : []), ...hits])].filter(inTag);
  }
}

const loaded = new Map<LanguageId, Reference>();
const loading = new Map<LanguageId, Promise<Reference>>();

/** Loads (once) the reference for a language. */
export function loadReference(language: LanguageId): Promise<Reference> {
  let promise = loading.get(language);
  if (!promise) {
    promise = files[language]().then((m) => {
      const ref = new Reference(m.default);
      loaded.set(language, ref);
      return ref;
    });
    loading.set(language, promise);
  }
  return promise;
}

/** The reference if it has loaded already (for synchronous editor hints). */
export function referenceIfLoaded(language: LanguageId): Reference | undefined {
  return loaded.get(language);
}

/** What the reference panel shows. */
export class ReferencePanel {
  open = $state(false);
  query = $state('');
  tag = $state<string | null>(null);
  /** The entry shown in full, by name. */
  selected = $state<string | null>(null);
  /** Bumped to ask the panel to focus its search box. */
  focusRequest = $state(0);

  /** Opens the panel on an entry (vim `K`, `:h name`), or searches if there's no exact match. */
  show(word: string) {
    this.open = true;
    this.query = word;
    this.tag = null;
    this.selected = word || null;
  }

  toggle() {
    this.open = !this.open;
    if (this.open) this.focusRequest++;
  }
}
